'use strict';
const {guide,parts,prints,electrical,plateSettingsHTML,printSeconds,costs}=window.BGB;
const REPO='https://github.com/demartinistudios/blooglyblob';
const $=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const partMap=Object.fromEntries(parts.map(p=>[p.id,p]));
const buildSteps=guide.steps.filter(s=>s.kind==='build');
const stepMap=Object.fromEntries(guide.steps.map(s=>[s.id,s]));
const printedPieceCount=parts.filter(p=>p.category==='Printed'&&p.qty>0).reduce((n,p)=>n+p.qty,0);
const stepName=id=>'step '+stepMap[id]?.number;
const stepLink=id=>stepMap[id]?`<a href="#step-${id}">${escape(stepName(id))}</a>`:escape(id);
// Authored text is escaped, then code, step references and the tool-list link become markup.
const rich=t=>escape(t).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\{step:([\w-]+)\}/g,(_,id)=>stepLink(id)).replaceAll('{tools}','<a href="#parts/tools">tool list</a>');
const plain=t=>String(t??'').replace(/`([^`]+)`/g,'$1').replace(/\{step:([\w-]+)\}/g,(_,id)=>stepName(id)).replaceAll('{tools}','tool list');
const S=id=>stepLink(id);

// Progress lives in this browser only. There is no migration layer: ticks for retired
// step IDs stay stored but never count, because progress counts only current build steps.
const KEY='blooglyblob-guide';
function loadState(){
 try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&Array.isArray(s.steps)&&Array.isArray(s.stock))return s}catch{}
 return {steps:[],stock:[]};
}
const state=loadState();
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}updateProgress()}
function updateProgress(){const complete=buildSteps.filter(s=>state.steps.includes(s.id)).length;$('#progress-count').textContent=`${complete} / ${buildSteps.length}`;$('#progress').max=buildSteps.length;$('#progress').value=complete;document.querySelectorAll('[data-navstep]').forEach(a=>a.classList.toggle('done',state.steps.includes(a.dataset.navstep)))}

const mainRefs=[['start','Meet BlooglyBlob'],['before-you-start','Before you start'],['notes','Build notes'],['safety','Safety & responsibility'],['parts','Parts & supplies'],['cost','Build cost'],['hardware','Fasteners & screw key'],['electrical','Electrical reference'],['software','Software reference']];
$('#reference-nav').innerHTML='<h3>Reference</h3>'+mainRefs.filter(([id])=>!['start','before-you-start'].includes(id)).map(([id,n])=>`<a href="#${id}" data-route="${id}">${n}</a>`).join('');
let chap='';$('#step-nav').innerHTML=buildSteps.map(s=>{const h=chap===s.chapter?'':`<h3>${escape(s.chapter)}</h3>`;chap=s.chapter;return h+`<a href="#step-${s.id}" data-route="step-${s.id}" data-navstep="${s.id}"><span class="num">${s.number}</span>${escape(s.title)}</a>`}).join('');

function stepNavigation(s){
 const i=buildSteps.findIndex(x=>x.id===s.id),prev=buildSteps[i-1],next=buildSteps[i+1];
 const done=next?'':`<div class="notice info build-complete"><b>Build complete.</b> Your robot is finished. Press the button and say hello.</div>`;
 const nextLink=next?`<a class="button primary next-step" data-next-step href="#step-${next.id}"><small>${next.chapter!==s.chapter?'Next chapter: '+escape(next.chapter):'Next'}</small>Step ${next.number} · ${escape(next.title)} →</a>`:'<a class="button primary" href="#start">Back to build overview</a>';
 return `${done}<div class="step-end"><label class="complete"><input type="checkbox" data-step="${s.id}" ${state.steps.includes(s.id)?'checked':''}>Done</label><div class="actions">${prev?`<a class="button" data-previous-step href="#step-${prev.id}">← Step ${prev.number}</a>`:'<a class="button" data-previous-step href="#before-you-start">← Before you start</a>'}${nextLink}</div></div>`;
}
function diagram(path,alt,caption='',{hero=false}={}){return `<figure class="diagram"${hero?' data-hero':''}><button data-zoom="${path}" aria-label="Enlarge ${escape(alt)}"><img src="${path}" alt="${escape(alt)}" ${hero?'loading="eager" fetchpriority="high"':'loading="lazy"'}></button><figcaption>${caption?`<p class="diagram-caption">${caption}</p>`:''}<button class="enlarge-label" data-zoom="${path}" aria-label="Enlarge ${escape(alt)}">${hero?'Take a closer look':'Enlarge diagram'} ↗</button>${hero?'<button type="button" data-hero-pause hidden>Pause animation</button>':''}</figcaption></figure>`}
function table(head,rows,cls=''){return `<div class="table-wrap ${cls}"><table><thead><tr>${head.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((x,i)=>`<td data-label="${escape(String(head[i]).replace(/<[^>]+>/g,''))}">${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function gather(items,hardware=false,tools=false){if(!Object.keys(items).length)return `<p class="fine">${hardware?'No screws in this step.':'Only the assemblies you’ve already built.'}</p>`;return `<ul>${Object.entries(items).map(([id,n])=>{const name=partMap[id]?.name||id;const img=partMap[id]?.image;return `<li><a href="#parts/${id}">${img?`<img class="thumb" src="${escape(img)}" alt="" loading="lazy">`:''}<span class="gather-name">${escape(name)}${name.replace('×','x')===id?'':` <small>${id}</small>`}${typeof n==='number'?'':`<small class="gather-amount">${escape(n)}</small>`}</span></a><span>${typeof n==='number'&&!tools?`× ${n}`:''}</span></li>`}).join('')}</ul>`}
const templates={'eye-windows':['downloads/eye-film-template.pdf','Download the full-size eye film template (PDF)'],'body-diffuser':['downloads/body-foam-template.pdf','Download the full-size body foam template (PDF)']};
function benchList(s){const isTool=id=>partMap[id]?.category==='Tool',pick=keep=>Object.fromEntries(Object.entries(s.parts).filter(([id])=>keep(id)));const parts=pick(id=>!isTool(id)),tools=pick(isTool),nParts=Object.keys(parts).length,nHw=Object.keys(s.hardware).length,nTools=Object.keys(tools).length,sections=[nParts,nHw,nTools].filter(Boolean).length;if(!sections)return '';const plural=(n,word)=>n?`${n} ${word}${n>1?'s':''}`:'';const count=[plural(nParts,'part'),plural(nHw,'fastener type'),plural(nTools,'tool')].filter(Boolean).join(', ');return `<details class="bench-list${sections===1?' single':sections===3?' triple':''}" open><summary>You’ll need <span class="bench-count">${count}</span></summary><div class="gather">${nParts?`<section><h2>Parts</h2>${gather(parts)}</section>`:''}${nHw?`<section><h2>Fasteners</h2>${gather(s.hardware,true)}<a class="fine" href="#hardware">Match lengths on the screw key</a></section>`:''}${nTools?`<section><h2>Tools</h2>${gather(tools,false,true)}</section>`:''}</div></details>`}
function stepLinks(s){if(s.id==='print-plates')return '';const links=[];
 if(s.id==='workbench')links.push('<a class="button primary" href="#parts">Open Parts & supplies</a>','<a class="button" href="#notes">Build notes</a>');
 if(s.chapter==='Pi software')links.push('<a class="button" href="#software">Software reference</a>');
 if(s.id==='fit-position')links.push('<a class="button" href="downloads/servo-fit-reference.md" download>Servo fit reference</a>');
 if(['head-harness','body-light-strand','servo-connections','light-connections','all-lights-test','power-jack','servo-power-capacitor','light-fuse-capacitor','body-light-test','power-wiring','shifter-wiring','button-audio-wiring','base-check','secure-wiring'].includes(s.id))links.push('<a class="button" href="#electrical">Open the wiring tables</a>');
 if(s.id==='light-fuse-capacitor')links.push('<a class="button" href="https://learn.adafruit.com/adafruit-neopixel-uberguide/seed-pixels">Adafruit strand wiring</a>');
 links.push('<a class="button" href="references.html">Component datasheets</a>');
 return `<div class="actions step-links">${links.join('')}</div>`}
function plateSettings(){return `<details id="plate-settings" class="plate-settings"><summary>Plate layouts, individual STLs & settings</summary><div class="plate-settings-content">${plateSettingsHTML}</div></details>`}
function servoTable(){return `<section class="details"><h2>Servo channels</h2>${table(['Servo','BCM / physical pin','Level shifter terminal','Fit position'],[['Robot-left shoulder','12 / 32','S1 C5','Arm hanging straight down'],['Robot-right shoulder','13 / 33','S2 D5','Arm hanging straight down'],['Head','16 / 36','S2 C5','Facing forward']],'cards')}<p class="fine"><a href="https://resources.kitronik.co.uk/pdf/25105-kitronik-clippable-servo-fs90mg-datasheet.pdf" target="_blank" rel="noreferrer">Kitronik FS90MG-CL servo datasheet ↗</a></p></section>`}
function commandCard(block){
 const kind=block.kind||'command',canCopy=kind!=='output'&&block.copy!==false;
 const context=kind==='command'?(block.context==='pi'?'On the Pi · SSH session':'On your computer'):kind==='config'?'File example':'Expected output';
 return `<div class="code-card" data-kind="${escape(kind)}"><div class="code-card-header"><div><span class="code-context">${context}</span>${block.label?`<strong class="code-label">${escape(block.label)}</strong>`:''}</div>${canCopy?`<button type="button" data-copy-code aria-label="Copy ${kind==='config'?'example':'command'}${block.label?' · '+escape(block.label):''}">Copy ${kind==='config'?'example':'command'}</button>`:''}</div><pre class="code-content" tabindex="0" aria-label="${escape(block.label||context)}"><code>${block.lines.map(escape).join('\n')}</code></pre>${canCopy?'<p class="copy-status" role="status" aria-live="polite" aria-atomic="true"></p>':''}</div>`;
}
function safety(value){return (value?(Array.isArray(value)?value:[value]):[]).map(e=>`<div class="safety safety-${escape(e.level)}" data-level="${escape(e.level)}" role="note"><strong class="safety-label">${escape(e.level.toUpperCase())}</strong><span class="safety-text">${rich(e.text)}</span></div>`).join('')}
function printInstructions(s){
 if(state.slicer!=='other')return actionPanels(s);
 return actionPanels({...s,actions:[
  'Import the STLs for the parts listed on plates 2 and 7.',
  'Use the quantities, orientations and per-part settings above.',
  'Use profiles for your printer and filament.',
  'Recreate the supports and blockers shown in the supplied project; STLs contain geometry only.',
  'Slice and inspect each batch before printing.',
  'Print the base, then its panels and grilles. Print the remaining parts as you build.'
 ],panels:[
  {title:'Load the STL files',textOnly:true,actions:[0,1,2]},
  {title:'Slice and print',textOnly:true,actions:[3,4,5]}
 ]});
}
function actionPanels(s){
 const panels=s.panels;
 return `<div class="action-sequence">${panels.map((panel,i)=>`<section class="action-panel${/^assets\/circuits\//.test(panel.image)?' action-panel-circuit':''}${/^assets\/setup\//.test(panel.image)?' action-panel-screenshot':''}${panel.image?'':' action-panel-command'}"><div class="action-panel-heading"><span aria-hidden="true">${i+1}</span><h2>${escape(panel.title)}</h2></div><div class="action-panel-body">${panel.image?diagram(panel.image,panel.title,panel.caption?rich(panel.caption):''):''}<div class="action-copy">${safety(panel.safety)}<ol class="instructions">${panel.actions.map(n=>`<li>${rich(s.actions[n])}</li>`).join('')}</ol>${(panel.codeBlocks||(panel.commands?.length?[{kind:'command',context:'computer',lines:panel.commands}]:[])).map(commandCard).join('')}${panel.links?.length?`<ul class="panel-links">${panel.links.map(link=>`<li><a href="${escape(link.url)}"${/^https:/.test(link.url)?' target="_blank" rel="noreferrer"':''}>${escape(link.label)}${/^https:/.test(link.url)?' ↗':''}</a></li>`).join('')}</ul>`:''}${panel.detail?`<details class="action-detail"><summary>${escape(panel.detail.title)}</summary>${diagram(panel.detail.image,panel.detail.title)}</details>`:''}</div></div></section>`).join('')}</div>`;
}
function stepHTML(s,all=false,partId){
 return `<article ${s.id==='print-plates'?`data-print-slicer="${state.slicer==='other'?'other':'bambu'}"`: ''} class="${[all?'full-print':'',s.chapter==='Pi software'?'setup-step':''].filter(Boolean).join(' ')}"><div class="step-head"><div><p class="eyebrow">${escape(s.chapter)+' · Step '+s.number+' of '+buildSteps.length}</p><h1 tabindex="-1">${escape(s.title)}</h1></div><span class="step-number" aria-hidden="true">${s.number}</span></div>${s.id==='print-plates'?printResources(partId):benchList(s)}${s.id==='light-fuse-capacitor'?harnessOverview():''}${s.safety?`<div class="step-safety">${safety(s.safety)}</div>`:''}${s.id==='print-plates'?printInstructions(s):actionPanels(s)}${s.id==='print-plates'?printTemplates():''}${s.note?`<div class="notice step-note">${rich(s.note)}</div>`:''}${s.check?`<div class="check"><strong>Ready to continue</strong>${rich(s.check)}</div>`:''}${templates[s.id]?`<p><a class="button" href="${templates[s.id][0]}" download>${templates[s.id][1]}</a> Print at 100% and check the scale bar.</p>`:''}${s.id==='fit-position'?servoTable():''}${stepLinks(s)}${stepNavigation(s)}</article>`;
}

function start(){
 const next=buildSteps.find(s=>!state.steps.includes(s.id))||buildSteps[0];
 const started=buildSteps.some(s=>state.steps.includes(s.id));
 const features=[
  ['M4 5h16v11H9l-5 4V5Zm4 4h8m-8 3h5','A voice of his own','Ask a question, swap stories or follow a curious tangent. Press his button and talk with him in your own words.'],
  ['M5 9h14v11H5zM9 5h6M12 2v3M8 13h1m6 0h1M9 17h6M2 11v6m20-6v6','Personality you can see','His arms rotate up and down, and his head turns from side to side. Glowing eyes and body lights give this little character his own presence.'],
  ['M9 18V5l11-2v12M9 7l11-2M9 18c0 4-6 4-6 1s6-4 6-1m11-3c0 4-6 4-6 1s6-4 6-1','A tiny dance party','Ask him to dance and he plays music with coordinated movements. When the song finishes, he returns to the conversation.'],
  ['M12 12l7-7M12 4a8 8 0 1 0 8 8M12 8a4 4 0 1 0 4 4M12 12h.01','A Galactic Scanner','Curious about the weather or something happening on Earth? He can search the web, complete with a spaceship-style scanner sound.'],
  ['M9 2h6M12 2v3M18 6l2-2M12 10v5l3 2M12 6a8 8 0 1 0 0 16 8 8 0 0 0 0-16','A little everyday help','Set a named countdown timer, ask what is running or cancel it by name. He lets you know when time is up with sound and lights.'],
  ['M4 20l4-1L20 7l-3-3L5 16l-1 4Zm10-13 3 3M4 4h5M4 8h2','Your own kind of robot','Choose filament colors, add paint, and adjust his voice or personality. The hardware designs and software are open source, ready for tinkering.']
 ];
 return `<article class="character-intro"><div class="intro-grid"><section><p class="eyebrow">Hello, Earth.</p><h1 tabindex="-1">Meet<br>BlooglyBlob.</h1><p class="lede">A curious little visitor from planet Meep. He chats, lights up, waves his arms—and can even throw a little dance party.</p><p class="intro-copy">An open-source, 3D-printed robot you can build yourself. He runs on Raspberry Pi and uses the <a href="https://developers.openai.com/api/docs/models/gpt-live-1" target="_blank" rel="noreferrer">OpenAI Live API</a> for voice conversations.</p>${started?`<div class="actions"><a class="button primary" href="#step-${next.id}">Continue your build →</a></div>`:''}</section>${diagram('assets/r22/main-front.png','BlooglyBlob lit up, with glowing goggle eyes, a rainbow mouth, a softly lit body, blue-violet head and hands, copper details and a black base','',{hero:true})}</div>
 <section class="character-capabilities" aria-labelledby="character-features-title"><p class="eyebrow">Get to know him</p><h2 id="character-features-title">A few of his favorite things.</h2><div class="character-features">${features.map(([path,title,copy])=>`<section><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg><h3>${title}</h3><p>${copy}</p></section>`).join('')}</div><div class="character-prompts"><span>Try saying</span><q>Tell me about space.</q><q>Let’s dance!</q><q>Set a five-minute timer.</q></div></section>
 <section class="character-build" aria-labelledby="character-build-title"><p class="eyebrow">Make a little character of your own</p><h2 id="character-build-title">Bring your BlooglyBlob to life.</h2><p>This is a hands-on build with 3D printing, soldering and Raspberry Pi setup. The guide takes you from loose parts to your first conversation.</p><div class="actions">${started?`<a class="button primary" href="#step-${next.id}">Continue your build →</a><a class="button" href="#before-you-start">Before you start</a>`:'<a class="button primary" href="#before-you-start">Start building →</a>'}<a class="button" href="#parts">Explore the parts</a></div><p class="fine">Voice features need an internet connection and your own OpenAI API key. API usage is billed to your account. <a href="#step-computer-ssh-key">See the Pi setup steps</a>.</p>
 <p class="notice"><b>DIY project, provided as is.</b> You are responsible for your build and its use; no safety or performance guarantees are made. This is a hobby project for adults, not a toy, and is not designed for children. <a href="#safety">Read the safety and responsibility notice</a>.</p>
 <p class="fine">Your parts checklist and completed steps are saved in this browser’s local storage. They don’t sync between devices. <a href="references.html">Component datasheets</a></p></section></article>`;
}

// Before you start (R1). Print figures come from print-data.json. Assembly time and cost are
// deliberately absent (owner decisions Q1, Q2). The browser check requires a line for every chapter.
const chapterWork={
 'Prepare':'Choose your colors and gather the tools.',
 'Print':'Print the plates and clean the parts.',
 'Base hardware':'Fit the nuts, grilles, vent, speakers and feet to the base.',
 'Pi software':'Set up the Pi from your computer, on the bench.',
 'Base boards and controls':'Mount the Pi, level shifters, WAGOs, audio, button and power jack.',
 'Base wiring':'Wire the base, then check it unpowered.',
 'Light test':'Prepare the body light input and test it with power.',
 'Frame and servos':'Fit the frame, servos, servo cables and horns.',
 'Head':'Build the head shelf, eyes, head harness, mouth and antenna.',
 'Body':'Fit the body light strand, body lights and diffuser.',
 'Arms':'Build the upper arms, elbows and hands.',
 'Backpack and belt':'Fit the backpack carrier, backpack and belt.',
 'Final wiring':'Connect the servo cables and light connectors, then inspect.',
 'First power-up':'Test all 16 lights and set the fit position.',
 'Head and arm mounting':'Attach the head shelf, arms, head and shoulder covers.',
 'Close up and test':'Check the first movement, secure the wiring and fit the bottom cover.'
};
function printTotals(){
 const plates=prints.filter(p=>p.purpose==='production');
 // The manifest's total seconds, truncated to minutes like each plate estimate; summing the truncated plate times undercounts.
 const minutes=Math.floor(printSeconds/60);
 return {plates:plates.length,time:`${Math.floor(minutes/60)} h ${minutes%60} min`,grams:Math.round(plates.reduce((n,p)=>n+p.estimate.grams,0))};
}
function beforeYouStart(){
 const first=buildSteps[0],print=printTotals(),chapters=[...new Set(buildSteps.map(s=>s.chapter))];
 const tools=parts.filter(p=>p.category==='Tool'&&!p.omitted);
 const map=chapters.map(c=>{const x=buildSteps.filter(s=>s.chapter===c);return [`<a href="#step-${x[0].id}">${escape(c)}</a><small class="chapter-steps">${x.length>1?`Steps ${x[0].number}–${x.at(-1).number}`:`Step ${x[0].number}`}</small>`,escape(chapterWork[c]||'')]});
 return `<article class="before-start"><p class="eyebrow">Start here</p><h1 tabindex="-1">Before you start</h1><p class="lede">What the build involves, what you need and where to begin.</p>
 <div class="notice info"><p><b>Your first action:</b> Choose your filament colors, then start printing plate 2 (the base).</p></div>
 <div class="actions"><a class="button primary" href="#step-${first.id}">Start step 1 · ${escape(first.title)} →</a></div>
 <h2>What the build involves</h2><ul class="reader-list">
 <li><b>Printing.</b> The slicer estimates ${print.time} of printing on ${print.plates} plates. It uses ${print.grams} g of PLA, plus any reprints. You can print in stages while you build. ${S('print-plates')} lists each plate and its estimate.</li>
 <li><b>Assembly.</b> ${buildSteps.length} steps in ${chapters.length} chapters, listed below. You solder some parts on the bench before you fit them.</li>
 <li><b>Software.</b> You set up the Raspberry Pi from your computer in the Pi software chapter.</li>
 <li><b>Voice.</b> Voice features need an internet connection and your own OpenAI API key. API usage is billed to your account.</li></ul>
 <h2>Skills this guide assumes</h2><p>You can solder, strip wire and run commands in a terminal. You know basic multimeter use. The guide does not teach these skills.</p>
 <section id="start-chapters" aria-labelledby="start-chapters-title"><h2 id="start-chapters-title">Chapters</h2>${table(['Chapter','What you do'],map)}</section>
 <h2>What you need</h2><ul class="reader-list"><li>A 3D printer for PLA. The guide supplies a Bambu project, and STL files for other slicers.</li><li>The purchased parts, fasteners and supplies in <a href="#parts">Parts & supplies</a>.</li><li>Materials you choose, such as diffuser foam, described in <a href="#notes">Build notes</a>.</li></ul>
 <h3>Tools</h3><ul class="reader-list" id="start-tools">${tools.map(p=>`<li><a href="#parts/${p.id}">${escape(p.name)} (${p.id})</a></li>`).join('')}</ul>
 <h2>How to read the steps</h2><ul class="reader-list"><li>Each step lists its parts, fasteners and tools at the top.</li><li>Robot-left and robot-right are the robot’s own sides.</li><li><a href="#notes">Build notes</a> explains the other words this guide uses.</li></ul>
 <h2>Work safely</h2><ul class="reader-list"><li>Read <a href="#safety">Safety & responsibility</a> before you begin.</li><li>Work unplugged unless a step tells you to connect power.</li><li>The front button starts a conversation. It does not turn the power off.</li></ul></article>`;
}
const priceFormat=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'});
const usd=value=>priceFormat.format(Number(value));
const priceDate=new Date(costs.checked_date+'T00:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});
const quotesFor=id=>costs.rows.filter(row=>row.id===id);
const singleSpools=`${costs.single_color_spools===1?'one':costs.single_color_spools} ${costs.single_color.toLowerCase()} spool${costs.single_color_spools===1?'':'s'}`; // plain text; escape in HTML
const shoppingScope=single=>`Shopping total, ${single?singleSpools:'guide colors'}`;
function priceSummary(){return `<section class="cost-summary" aria-label="Build cost estimates"><div><span class="eyebrow">Materials used</span><strong>${usd(costs.total)} <small>per robot</small></strong><p>Shopping total: ${usd(costs.single_color_total)} with ${escape(singleSpools)}, or ${usd(costs.shopping_total)} in the guide colors.</p></div><a class="button" href="#cost">Build cost & shopping list →</a><p class="cost-scope">Prices checked ${escape(priceDate)}. ${escape(costs.exclusions)}</p></section>`}
function partPrice(p){
 if(p.category==='Tool')return '';
 if(p.category==='Printed')return `<p class="part-price">${p.qty===0?'Optional print. Not in the build cost.':'Filament is counted by print plate.'} <a href="#cost">Build cost →</a></p>`;
 const quotes=quotesFor(p.id),excluded=quotes.every(q=>Number(q.used_quantity)===0),parent=quotes.every(q=>q.included_with)&&partMap[quotes[0].included_with];
 const line=parent?`Included with <a href="#parts/${parent.id}">${escape(parent.name)} (${parent.id})</a>`:excluded?'Not in the build cost.':`Materials used: ${usd(costs.part_totals[p.id])} per robot`;
 return `<div class="part-price"><p><b>${line}</b></p>${p.id==='C13'?'<p><a href="#cost">Filament weights and prices →</a></p>':quotes.filter(q=>!q.included_with).map(q=>`<p>${quotes.length>1?escape(q.name)+': ':''}<a href="${escape(q.url)}" target="_blank" rel="noreferrer">${escape(q.pack_label)} · ${usd(q.pack_price_usd)} ↗</a></p>`).join('')}</div>`;
}
// Single items show a bare count; a pack bought once shows its label.
const orderQuantity=r=>Number(r.pack_quantity)===1?String(r.buy_packs):r.buy_packs===1?escape(r.pack_label):`${r.buy_packs} × ${escape(r.pack_label)}`;
// Counted packs (100 washers) price per pack; sheets, rolls and tubes are measured, so each.
const packPrice=r=>`${usd(r.pack_price_usd)} ${r.category==='Filament'?'per spool':Number(r.pack_quantity)===1||['mm²','m','ml','g'].includes(r.unit)?'each':'per pack'}`;
function shoppingHTML(single=false){
 const rows=costs.rows.filter(r=>r.buy_packs>0 && (!single || r.category!=='Filament'));
 if(single){const filament=costs.rows.find(r=>r.plate_color===costs.single_color);rows.push({...filament,buy_packs:costs.single_color_spools,buy_cost:costs.single_color_filament});}
 return Object.keys(costs.categories).map(category=>`<details class="shopping-detail" ${category==='Filament'?'open':''}><summary>${escape(category)} <span>${usd(category==='Filament'&&single?costs.single_color_filament:costs.shopping_categories[category])}</span></summary>${costs.shopping_notes?.[category]?`<p class="fine">${escape(costs.shopping_notes[category])}</p>`:''}${table(['Item','Order quantity','Pack price','Line total'],rows.filter(r=>r.category===category).map(r=>[`<a href="#parts/${escape(r.id)}">${escape(r.name)}</a>${r.purchase_note?`<small>${escape(r.purchase_note)}</small>`:''}`,orderQuantity(r),`<a href="${escape(r.url)}" target="_blank" rel="noreferrer">${packPrice(r)} ↗</a>${(r.alternative_links||[]).map(link=>`<small><a href="${escape(link.url)}" target="_blank" rel="noreferrer">${escape(link.label)} ↗</a></small>`).join('')}`,usd(r.buy_cost)]),'cards')}</details>`).join('');
}
function costHTML(){
 return `<p class="eyebrow">Plan your budget</p><h1 tabindex="-1">Build cost</h1><p class="lede">${escape(costs.basis)}</p>
 <div class="cost-options">
 <section><h2>Materials used</h2><div class="cost-total"><strong>${usd(costs.total)}</strong></div><p>The parts and material consumed by one robot in the guide colors. Leftover supplies are not charged here.</p><button class="text-button" data-cost-materials>See material breakdown ↓</button></section>
 <section><h2>Shopping total · ${escape(singleSpools)}</h2><div class="cost-total"><strong>${usd(costs.single_color_total)}</strong></div><p>All listed parts and supply packs, plus ${escape(singleSpools)} of PLA. Every part prints ${escape(costs.single_color.toLowerCase())}, so the antenna ball is opaque, not clear.</p><p class="fine">Filament: ${usd(costs.single_color_filament)}</p></section>
 <section><h2>Shopping total · guide colors</h2><div class="cost-total"><strong>${usd(costs.shopping_total)}</strong></div><p>The same parts and supply packs, plus ${costs.palette_spools} filament spools in the guide colors.</p><p class="fine">Filament: ${usd(costs.shopping_categories.Filament)}</p></section>
 </div>
 <p>Both shopping totals assume you already have the tools, but none of the parts or consumables. Whole packs leave extras for future projects.</p>
 <p class="fine">USD · prices checked ${escape(priceDate)}. Prices vary. ${escape(costs.exclusions)} Check each link before ordering.</p>
 <h2>Shopping list</h2><p>Order the quantities below, skipping supplies you already have. Shared packs and bundled accessories are counted once. Choose each filament color on its product page.</p>
 <fieldset class="slicer-choice"><legend>Filament to purchase</legend><label><input type="radio" name="cost-filament" value="palette" checked>Guide colors</label><label><input type="radio" name="cost-filament" value="single">${escape(singleSpools[0].toUpperCase()+singleSpools.slice(1))}</label></fieldset>
 <p class="shopping-total" aria-live="polite"><strong id="shopping-total">${usd(costs.shopping_total)}</strong> · <span id="shopping-scope">${escape(shoppingScope(false))}</span></p>
 <div id="shopping-list">${shoppingHTML()}</div>
 <h2 id="cost-materials" tabindex="-1">Materials used per robot</h2><p>The selected plates use about ${Math.round(Number(costs.filament_grams)/10)*10} g of filament.</p>
 <dl class="cost-categories">${Object.entries(costs.categories).map(([name,value])=>`<div><dt>${escape(name)}</dt><dd>${usd(value)}</dd></div>`).join('')}</dl><p>${escape(costs.allowances)}</p>${Object.keys(costs.categories).map(category=>`<details class="cost-detail"><summary>${escape(category)} <span>${usd(costs.categories[category])}</span></summary>${category==='Filament'?`<p>${escape(costs.filament_note)}</p>`:''}${table(['Item','Amount used','Cost used','Pack price'],costs.rows.filter(r=>r.category===category).map(r=>[`<a href="#parts/${escape(r.id)}">${escape(r.name)}</a><small>${escape(r.id)}</small>`,`${escape(r.used_quantity)} ${escape(r.unit)}`,usd(r.cost_used),`<a href="${escape(r.url)}" target="_blank" rel="noreferrer">${escape(r.pack_label)}${r.included_with?'':' · '+usd(r.pack_price_usd)} ↗</a>${r.note?`<small>${escape(r.note)}</small>`:''}`]),'cards')}</details>`).join('')}<p><a href="#parts">Back to Parts & supplies →</a></p>`;
}
function card(p){
 const media=p.image?`<button data-zoom="${escape(p.image)}" aria-label="Enlarge ${escape(p.name)} drawing" class="part-reference"><img loading="lazy" src="${escape(p.image)}" alt="${escape(p.name)}, drawing"></button>`:`<div class="no-image" aria-hidden="true">${p.id}</div>`;
 const buy=p.link?`<p><a href="${escape(p.link)}" ${p.link.startsWith('downloads/')?'download':'target="_blank" rel="noreferrer"'}>${p.link.startsWith('downloads/')?'Download STL':'View product ↗'}</a></p>`:p.category==='Printed'?'':'<p class="fine">Any part that meets the description above.</p>';
 const usedIn=p.steps.length?`<p class="fine">Used in: ${p.steps.map(id=>stepLink(id)).join(', ')}</p>`:'';
 const plate=p.category==='Printed'&&!p.omitted?(prints.some(pl=>pl.parts.includes(p.id))?`<p class="fine"><a href="#step-print-plates/${p.id}">Which plate prints ${p.id}</a></p>`:'<p class="fine">Not on the supplied plates; print it from its STL if you want it.</p>'):'';
 return `<article class="part-card" id="part-${p.id}">${media}<div class="part-body"><span class="part-id">${p.id} / ${escape(p.category)}</span><h2>${escape(p.name)}</h2><span class="badge">${p.qty===0?'Optional: 1':typeof p.qty==='number'?p.qty+' '+(p.category==='Printed'?'to print':'needed'):escape(p.qty)}${p.optional&&p.qty!==0?` · ${escape(p.optional_label||'Optional')}`:''}</span>${partPrice(p)}<p>${rich(p.description)}</p>${p.category==='Printed'?'':`<p class="source-state">${escape(p.verification)}</p>`}${p.category==='Tool'||p.category==='Printed'||p.id==='C13'?buy:''}${(p.additional_links||[]).filter(a=>!quotesFor(p.id).some(q=>q.url===a.url)).map(a=>`<p><a href="${escape(a.url)}" ${a.url.startsWith('downloads/')?'download':'target="_blank" rel="noreferrer"'}>${escape(a.label)}${a.url.startsWith('downloads/')?'':' ↗'}</a></p>`).join('')}${usedIn}${plate}<label class="stock"><input type="checkbox" data-stock="${p.id}" ${state.stock.includes(p.id)?'checked':''}>${p.category==='Printed'?'Printed it':'Got it'}</label></div></article>`;
}
// Filters survive navigating to a step and back.
const partsFilter={q:'',c:'',stock:''};
function partsHTML(id){if(id==='tools'){id='';partsFilter.q='';partsFilter.c='Tool';partsFilter.stock='';}else if(partMap[id]){partsFilter.c='';partsFilter.stock='';}return `<p class="eyebrow">Parts for one robot</p><h1 tabindex="-1">Parts & supplies</h1><p class="lede">Everything needed for one robot. Search by name, part ID, product number or purpose. Quantities are what one robot uses; packs may contain more. Optional items are marked.</p>${priceSummary()}<div class="notice info">Tick “Got it” or “Printed it” once you have the full quantity ready. Your checklist is saved in this browser only. Read the <a href="#notes">build notes</a> before shopping. Left and right mean the robot’s own sides. All white diffuser foam is 4 mm Plastazote LD45; the audio lid lining uses 1 mm foam (C10). Many parts have <a href="references.html">datasheets</a> you can open on the publisher’s site.</div><div class="toolbar"><label class="sr-only" for="search">Search parts</label><input id="search" type="search" placeholder="Try “eye”, “M3”, “WAGO” or “AR01”" value="${escape(id||partsFilter.q)}" aria-label="Search parts"><select id="category" aria-label="Filter part category"><option value="">All categories</option>${['Printed','Purchased','Fastener','Consumable','Tool'].map(x=>`<option${partsFilter.c===x?' selected':''}>${x}</option>`).join('')}</select><select id="stock-filter" aria-label="Filter your checklist"><option value="">Everything</option><option value="missing"${partsFilter.stock==='missing'?' selected':''}>Still to get or print</option><option value="owned"${partsFilter.stock==='owned'?' selected':''}>Ready</option></select></div><p id="result-count" class="fine" aria-live="polite"></p><div id="parts-list" class="parts-grid"></div>`}
function filterParts(){const q=$('#search').value.toLowerCase().trim(),c=$('#category').value,stock=$('#stock-filter').value;if(!/^[a-z0-9]+$/i.test(q)||!partMap[q.toUpperCase()])partsFilter.q=$('#search').value;partsFilter.c=c;partsFilter.stock=stock;const listed=parts.filter(p=>!p.omitted);const exact=listed.find(p=>p.id.toLowerCase()===q);const found=listed.filter(p=>(!exact||p===exact)&&(!c||p.category===c)&&(!q||[p.id,p.name,p.description].join(' ').toLowerCase().includes(q))&&(!stock||(stock==='owned')===state.stock.includes(p.id)));$('#result-count').textContent=`Showing ${found.length} of ${listed.length}`;$('#parts-list').innerHTML=found.length?found.map(card).join(''):'<p class="empty">No matching parts. Try a shorter search or clear the filters.</p>'}
function hardware(){const rows=Object.entries(guide.totals).map(([id,n])=>[escape(partMap[id]?.name||id),n,guide.steps.filter(s=>s.hardware[id]).map(s=>`${stepLink(s.id)}: ${s.hardware[id]}`).join(' · ')]);return `<p class="eyebrow">Pick the right screw</p><h1 tabindex="-1">Fasteners & actual-size screw key</h1><p class="lede">The build uses ${Object.entries(guide.totals).filter(([id])=>id.startsWith('M2x')).reduce((n,[,q])=>n+q,0)} M2 screws, ${Object.entries(guide.totals).filter(([id])=>id.startsWith('M3x')).reduce((n,[,q])=>n+q,0)} M3 screws and the ${guide.totals.CENTER} center screws supplied with the servos. Each row lists one fastener and how many each step uses.</p><div class="downloads"><div class="download-card"><b>US Letter</b><a class="button primary" href="downloads/screw-key-letter.pdf" download>Download Letter PDF</a></div><div class="download-card"><b>A4</b><a class="button primary" href="downloads/screw-key-a4.pdf" download>Download A4 PDF</a></div></div><div class="notice"><b>Print at 100% (actual size).</b> Turn off “Fit”, “Shrink” and “Scale to page”. Measure the printed 50 mm ruler and 20 mm square before you match screws. Do not match screws against a screen.</div><h2>Measuring screws</h2><p>Measure a screw from under its head to the tip. Measure a countersunk screw including its head. M2 and M3 are the thread diameters. Keep each servo center screw with its horn, apart from your M2 stock. Its size is not specified.</p><p>Use standard hex nuts. The three head screws are M2×8 button heads, with no washers or plugs. The M2 kit in the parts list includes them. Their Ø4.0 × 1.55 mm recesses suit Ø3.5 × 1.3 mm heads, so measure yours. Other M2 heads must fit within Ø3.8 × 2 mm. M3 socket heads must fit within Ø5.5 × 3 mm. The countersunk screws have a Ø6 mm, 90° head. Stop tightening once a joint holds without bending the print.</p>${table(['Fastener','Quantity','Used in (step: quantity)'],rows)}<h2>Washers</h2><p>The eyes use four thin metal M2 washers. The speakers use eight M3 washers, about 0.5 mm thick. Check them against your speaker tabs.</p><h2>Joints that are easy to mix up</h2><ul class="reader-list"><li>Head shell (GS20) to head shelf (P08): three M2×8 button-head screws and M2 nuts, no washers.</li><li>Head horn adapter (P14) to head shelf (P08): three M3×8 screws and M3 nuts.</li><li>Lower foam collar (P01) and both uprights (P43, P02) to the base: two M3×16 screws.</li><li>Lower and upper light brackets (P11, P42) to the front upright: two M3×14 countersunk screws. The head-servo bracket’s front screw is an M3×10 countersunk.</li><li>Head servo ears: an M2×8 at the front ear, an M2×6 at the rear ear.</li><li>Level shifters (S1, S2) on their posts in the base: four M2×10 screws.</li><li>Front microphone grille (FB41): four M3×6 screws and M3 nuts, no washers.</li><li>Rear vent (FB03): four M3×12 screws and M3 nuts, no washers.</li><li>Bottom cover (FB02): four M3×12 screws.</li><li>WAGOs: double-sided tape, with no mounting screws or nuts.</li></ul>`}

function printResources(partId){
 const match=partMap[partId],selected=match?prints.filter(p=>p.parts.includes(partId)):[];
 const context=match?`<p class="notice info">${escape(partId)} · ${escape(match.name)}: ${selected.length?selected.map(p=>escape(p.name)).join(', '):'not on the supplied plates'}. <a href="#step-print-plates">Show the full printing step</a></p>`:'';
 return `<p class="lede">${printedPieceCount} printed pieces / ${parts.filter(p=>p.category==='Printed'&&p.qty>0).length} types on ten PLA plates. Start with the base and its panels and grilles. Print the rest as you build.</p>
 <fieldset class="slicer-choice"><legend>Slicer</legend>${[['bambu','Bambu Studio'],['other','Other slicer']].map(([value,label])=>`<label><input type="radio" name="slicer" value="${value}" ${value===(state.slicer==='other'?'other':'bambu')?'checked':''}>${label}</label>`).join('')}</fieldset>
 <div class="actions"><a data-slicer="bambu" class="button primary" href="downloads/BlooglyBlob-PLA.3mf" download>Bambu project · all plates</a><a class="button" href="downloads/BlooglyBlob-STL.zip" download>All STL files (ZIP)</a><a data-slicer="bambu" class="button" href="downloads/BlooglyBlob-PETG-ball.3mf" download>Optional PETG ball</a></div>
 <p class="fine">Choose your own colors. Print one antenna ball: PLA on plate 10 or the optional clear PETG version.</p>
 <p class="fine" data-slicer="other"><a href="downloads/BlooglyBlob-PLA.3mf" download>Project reference (3MF)</a> · Layouts and estimates below use the supplied Bambu project.</p>
 ${context}${plateSettings()}
 <p class="fine">Optional pointing hand: <a href="downloads/stl/AR07.stl" download>AR07 STL</a> · print fingers up, wrist peg down.</p>`;
}
function printTemplates(){return `<details><summary>Cutting templates</summary><p><a href="downloads/eye-film-template.pdf" download>Eye film (PDF)</a> · <a href="downloads/eye-film-template.svg" download>Eye film (SVG)</a> · <a href="downloads/body-foam-template.pdf" download>Body foam (PDF)</a> · <a href="downloads/body-foam-template.svg" download>Body foam (SVG)</a>. Print templates at 100% and check the scale bar.</p></details>`;}

function harnessOverview(){return `<section class="harness-overview action-panel-circuit"><h2>What connects between assemblies</h2><div class="action-panel-body">${diagram('assets/circuits/harness-connections.svg','The body light connector and the head light connector are three-pin JST-SM pairs. Each servo cable ends in bare power, ground and signal wires for its terminals.','Both light connectors, and the three wire ends of a servo cable.')}<div class="action-copy"><p>Lighting power and data run in one chain: base half → body light connector → six body lights → head light connector → first eye → eye cable → second eye → mouth lead → eight mouth lights.</p><p>The servo cables stay on the fixed frame.</p></div></div></section>`}
function referenceFigures(label,figures){return `<div class="reference-gallery" aria-label="${label}">${figures.map(([file,title])=>diagram(file,title,escape(title))).join('')}</div>`}
function masterWiring(){return `<details class="reference-topic" id="reference-master" open><summary>Master wiring diagram</summary><div class="reference-content">
 <p>Follow each wire between the components. A dot marks a join. Crossing wires without a dot are not joined. Pi labels are physical header pin numbers. For physical placement, use the assembly steps and the close-ups below.</p>
 <div class="master-tools" aria-label="Master diagram view"><button data-wiring-detail aria-pressed="false">Larger labels</button><a href="assets/circuits/master-wiring.svg" target="_blank" rel="noreferrer">Open full-size SVG ↗</a><a href="assets/circuits/master-wiring.svg" download>Download SVG</a></div>
 <figure class="master-wiring"><div class="master-window" tabindex="0" role="region" aria-label="Master wiring diagram; scroll to follow connections" aria-describedby="master-help"><img src="assets/circuits/master-wiring.svg" width="2640" height="2120" alt="One connected master wiring diagram: power jack and Pi supply, WAGO ports, the light fuse and capacitors, all twelve Pi header connections, three servos, button, USB audio and the 16-light lighting chain. Every component appears once, with continuous wires between its terminals and the next component."></div><figcaption id="master-help">The whole circuit in one drawing, with schematic positions and contact order. Larger labels zooms in; scroll to follow a wire.</figcaption></figure>
 </div></details>`}
function electricalHTML(){return `<article class="electrical-reference"><p class="eyebrow">Wiring lookup</p><h1 tabindex="-1">Electrical reference</h1><p class="lede">Start with the complete wiring map. Choose a topic for terminal tables and close-ups.</p>
 <nav class="reference-picker" aria-label="Electrical topics">${[
 ['power','Power & WAGO','Supply, light fuse and port numbers','assets/cartoons/E06.svg'],
 ['signals','Pi & button','Header pins and level shifters','assets/cartoons/E15.svg'],
 ['lights','Lights','Body → eyes → mouth','assets/cartoons/E03.svg'],
 ['connectors','Plugs & servos','Connections between assemblies','assets/cartoons/E10.svg']
 ].map(([id,title,note,src])=>`<button data-reference="${id}" aria-controls="reference-${id}" aria-expanded="false"><img src="${src}" alt=""><span><b>${title}</b><small>${note}</small></span></button>`).join('')}</nav>
 <div class="reference-shortcuts"><button data-reference="master" aria-controls="reference-master" aria-expanded="true">Master wiring diagram</button><button data-reference="layout" aria-controls="reference-layout" aria-expanded="false">Layout & cable routes</button><button data-reference="routing" aria-controls="reference-routing" aria-expanded="false">Wire lengths & insulation</button><button data-reference="tests" aria-controls="reference-tests" aria-expanded="false">Assembly checks</button><button data-reference="names" aria-controls="reference-names" aria-expanded="false">Circuit labels & datasheets</button></div><p class="reference-safety">Check wiring with the supply unplugged. Assembly checks lists each test in build order.</p>
 ${masterWiring()}
 <details class="reference-topic" id="reference-layout"><summary>Find the components in the base</summary><div class="reference-content">${referenceFigures('Physical component locations',[['assets/community/base-electrical-layout.svg','Open-bottom layout: USB front, SD rear; S1 nearer Pi, S2 nearer audio'],['assets/community/wago-port-order.svg','WAGO ports: 1 on the right in this open-bottom view']])}<p>View through the open bottom. The WAGO wire entries face the front, and their levers face you. The power jack (J1) is at the robot-left end of the base’s rear face. Match the written labels, not the order in a wiring diagram.</p>${referenceFigures('Power lead and USB connections',[['assets/community/pi-power-route-depth.svg','Short Pi power lead to W1/2 and W3/2'],['assets/community/usb-audio-route-depth.svg','USB connection points on the Pi and audio module']])}<p>The Pi power lead is 150 mm or shorter, plug included. Test-route the USB extension around the cradle with a relaxed bend, without pulling on either socket.</p></div></details>
 <details class="reference-topic" id="reference-power"><summary>Power & WAGO terminals</summary><div class="reference-content">
 <div class="reference-pair">${diagram('assets/power-diagram.svg','Power distribution: Pi, servo and lighting branches','The three power branches from W1.')}<div>
 <p>Use the specified Mean Well GST40A05-P1J (5 V, 5 A) power supply. The circuit is designed around its output and protection characteristics; do not substitute another supply.</p><p>Fit the specified T1 A time-delay fuse in the lighting supply. Do not bypass it or fit a higher-rated fuse.</p>
 <p>W2/3 means WAGO W2, port 3. Ports are numbered 1 to 5 from the robot-right end. All five ports in one WAGO are joined.</p>
 <ul class="reference-notes"><li>A red 18 AWG wire joins W1/3 directly to W2/1. An 18 AWG wire joins W3/3 to W4/1.</li><li>Each port takes one untinned wire. The speaker outputs never connect to W3 or W4.</li></ul></div></div>
 <h3>Find your WAGO port</h3>
 ${referenceFigures('WAGO port diagrams',[['assets/circuits/w1-reference.svg','W1 port assignments'],['assets/circuits/w3-reference.svg','W3 port assignments'],['assets/circuits/w2-reference.svg','W2 port assignments'],['assets/circuits/w4-reference.svg','W4 port assignments']])}
 <details class="reference-table"><summary>All power connections as a table</summary>${table(electrical.power.header,electrical.power.rows,'cards')}</details>
 <p class="reference-build">Assembly: ${S('power-wiring')} · ${S('servo-power-capacitor')} · ${S('light-fuse-capacitor')}</p></div></details>
 <details class="reference-topic" id="reference-signals"><summary>Pi pins, level shifters & button</summary><div class="reference-content">
 <p>Pin numbers are <b>physical header pin numbers</b>. Button LED: pin 4 (+5 V) → R1 (1 kΩ) → LED +, and pin 20 (GND) → LED −. The button switch uses pin 11 (GPIO17) and pin 14 (GND).</p>
 <p>S1 and S2 shift signals from 3.3 V to 5 V. They do not power the servos or lights. The !D5 outputs stay unused. The cut <a href="https://learn.adafruit.com/adafruit-pixel-shifter/pinouts" target="_blank" rel="noreferrer">Neo jumper</a> on each board disables only its onboard test LED. Both signal channels stay active.</p>
 ${referenceFigures('Show Pi and button connections',[['assets/circuits/s1-inputs.svg','Pi to S1'],['assets/circuits/s2-inputs.svg','Pi to S2'],['assets/circuits/button-led.svg','Button leads']])}
 <details class="reference-table"><summary>All Pi and signal connections as a table</summary>${table(electrical.signal.header,electrical.signal.rows,'cards')}</details>
 <p class="reference-build">Assembly: ${S('pi-shifters')} · ${S('button-leads')} · ${S('shifter-wiring')} · ${S('button-audio-wiring')}</p></div></details>
 <details class="reference-topic" id="reference-lights"><summary>Lighting: data order & power branches</summary><div class="reference-content">
 <p><b>Data:</b> GPIO18 → S1 DAT / D5 → R2 (330 Ω) → body light connector → body lights 0–5 → head light connector → eyes 6–7 → mouth 8–15. Each DOUT connects to the next DIN.</p>
 <p><b>Power:</b> F2 and C2 feed the base half of the body light connector. +5 V and GND follow the same chain as DATA: through the six body lights, the head light connector, both eyes and the mouth lead to the mouth.</p>
 <p>16 lights · GRB order · brightness 128/255. The light test lights all 16. In normal use, the body and eyes animate, and the mouth lights while the robot talks or dances.</p>
 ${referenceFigures('Show the lighting connections',[['assets/circuits/body-output.svg','Body light 5 to the head light connector'],['assets/circuits/head-power.svg','Head half to the first eye'],['assets/circuits/head-data.svg','Eyes and mouth']])}
 <p class="reference-build">Assembly: ${S('light-fuse-capacitor')} · ${S('head-harness')} · ${S('body-light-strand')}</p></div></details>
 <details class="reference-topic" id="reference-connectors"><summary>Light connectors & servo terminals</summary><div class="reference-content">
 <div class="reference-pair">${diagram('assets/circuits/harness-connections.svg','The two light connectors are JST-SM pairs. Servo wires go straight into WAGO ports and level shifter terminals.','Both light connectors, and the three wire ends of a servo cable.')}<div><p><b>Body light connector (BODY LIGHT):</b> the base half stays in the base. The body half is the plug on the strand’s input end.</p><p><b>Head light connector (HEAD LIGHT):</b> the body half stays with the body, on the head light cable. The head half stays with the head, on the head harness. The joined connector sits inside the head, on top of the mouth LED cassette (P30).</p><p><b>Pins or sockets:</b> sockets on the base half and on the head light connector’s body half; pins on the strand’s input plug and on the head half.</p><p>Both light connectors are JST-SM, 2.5 mm (large), and carry +5 V, DATA and GND. The eyes use JST-SH, 1.0 mm (small) plugs. The mouth lead is soldered to the mouth stick.</p><p>The head light cable rises through the upper foam collar (P01) and the head shelf’s side entry.</p><p>The servos stay on the frame. Their cables reach their terminals with slack, clear of the horns.</p></div></div>
 ${table(['Servo','Power / ground','Signal'],[['Robot-left shoulder (LEFT)','W2/2 · W4/2','S1 C5'],['Robot-right shoulder (RIGHT)','W2/3 · W4/3','S2 D5'],['Head (HEAD)','W2/4 · W4/4','S2 C5']],'cards')}
 <p class="reference-build">Routing: ${S('light-connections')} · ${S('servo-connections')}.</p></div></details>
 <details class="reference-topic" id="reference-routing"><summary>Wire lengths, routing & insulation</summary><div class="reference-content">
 ${table(['Item','Requirement'],[['Pi power lead (PI POWER)','24 AWG. Plug and lead together ≤150 mm, with no extension. Release its tie to unplug it.'],['Servo feed','Red 18 AWG, W1/3 to W2/1. Test-route it without tension before cutting.'],['Light fuse holder','Cut its loop in the middle. Extend either end as needed with 18 AWG, soldered and insulated on the bench.'],['C1 / C2','1000 µF, 10 V. The stripe marks the negative lead. Insulate each lead separately at the rubber-seal end. Keep the opposite vent end clear.'],['Supports','Adhesive tie squares (C17) inside the base hold the ties. Tie the fuse holder and each capacitor by its body, not its wires. Keep the fuse opening reachable.'],['Clearance','Wiring and tie locks stay at least 4 mm from the bottom cover. The harness opening stays smooth. The microSD card, frame screws and moving parts stay clear.']],'cards')}
 <p>No wiring attaches to the bottom cover.</p><p class="reference-build">Assembly: ${S('power-wiring')} · ${S('light-connections')}</p></div></details>
 <details class="reference-topic" id="reference-tests"><summary>Assembly checks & expected results</summary><div class="reference-content">
 ${table(['Stage','Check / expected result'],[[`${S('base-check')} and ${S('power-up-inspection')} · unpowered`,'J1 reaches all four WAGOs. The body light +5 V reaches W1 only through F2 (T1 A). No +5 V-to-ground short.'],[`${S('body-light-test')} · strand input`,'The strand is still uncut. F2 is fitted and servo cables are disconnected. The first 16 pebbles light in order. Mark INPUT only after this passes.'],[`${S('all-lights-test')} · all 16 lights`,'All 16 lights light in order, then show red, green and blue. The head and arms are still off their shafts.'],[`${S('fit-position')} to ${S('first-movement')}`,'Hold the fit position, seat the head shelf and arms while the servos hold, then check movement and cable slack.'],[`${S('secure-wiring')} · before closing`,'Plugs and WAGO levers are seated and joints insulated. Wires and tie locks sit at least 4 mm clear of the cover seat.'],[`${S('finished-robot')} · cover fitted`,'Conversation, sound, movement and lighting work with the cover fitted.']],'cards')}
 </div></details>
 <details class="reference-topic" id="reference-names"><summary>Written labels & component documents</summary><div class="reference-content">
 <p>These labels are written on the parts. They differ from parts-list IDs: C1 is a capacitor, not consumable C01.</p>
 ${table(['Label','Component'],[['J1','Power jack (E18), at the robot-left end of the base’s rear face'],['PI POWER','Pi power lead (E22)'],['BODY LIGHT','Body light connector (E10): base half and body half'],['HEAD LIGHT','Head light connector (E10): body half and head half'],['W1 / W2 / W3 / W4','Input / servo power / ground / servo ground WAGO (E06)'],['F2','Light fuse (T1 A time-delay), in the E07 holder'],['C1 / C2','Servo capacitor / light capacitor (E08)'],['S1 / S2','Level shifters (E15)'],['R1 / R2','1 kΩ button LED resistor / 330 Ω data resistor'],['LEFT / RIGHT / HEAD','Robot-left arm / robot-right arm / head servo cable'],['INPUT','The input end of the body light strand (E05)']],'cards')}
 <p><a href="references.html">Open component datasheets</a></p></div></details></article>`}

function notesHTML(){return `<p class="eyebrow">Build notes</p><h1 tabindex="-1">What to know before you build</h1><p class="lede">Materials to choose, the words this guide uses and how to read its drawings.</p>
 <h2>Materials</h2><ul class="reader-list"><li>Eye, mouth and body diffusers: <a href="https://coscomcosplaysupplies.com/products/plastazote-ld45">white Plastazote LD45, 4 mm thick</a>. The shop sells other thicknesses, so choose 4 mm.</li><li>Eye windows: any clear, flexible transparency sheet that lies flat in the groove without forcing the lip. Cut them with the full-size template.</li><li>Audio lid lining: nonconductive closed-cell foam, 1 mm thick (C10).</li><li>Double-sided tape (C16) holds the WAGOs and the audio case. The audio patch must be under 1 mm thick.</li><li>Adhesive tie squares (C17), 1 inch, hold the base wiring.</li><li>Nut glue: two-part epoxy (C09), or optional CA gel (C18). The build glues 15 nuts: eight M2 board nuts, four M3 bottom cover nuts and three M3 audio cradle nuts.</li><li>Light fuse: fit the specified T1 A time-delay fuse. Do not bypass it or fit a higher-rated fuse. A jammed servo can keep pushing and overheat; unplug the supply immediately.</li></ul>
 <h2>Words used in this guide</h2><p>These words have a specific meaning in this guide. Each step also defines a word where it first uses it.</p><dl class="glossary">${[
 ['Base','The black printed base (FB01) and everything mounted in it.'],
 ['Base-half wires','The +5 V, GND and DATA wires from F2, C2 and S1 D5 to the base half. R2 sits in the DATA wire.'],
 ['Body light connector (BODY LIGHT)','The first three-pin JST-SM pair (E10), between the base and the body light strand. Its halves are the base half, which stays in the base, and the body half: the plug on the strand’s input end. Both halves are labeled BODY LIGHT.'],
 ['C1, C2','The servo capacitor (C1) and the light capacitor (C2), 1000 µF (E08).'],
 ['Connect (a wire to a board)','Fasten the wire in the named terminal, such as S1 D5, or push a jumper lead onto the named Pi pin.'],
 ['Eye input lead','One half of the 200 mm JST-SH cable (E11), cut in the middle. It joins the head half to the first eye’s IN socket.'],
 ['F2','The light fuse, T1 A time-delay, in the fuse holder (E07).'],
 ['Fit position','The servo position set by make pi-servo-fit: head facing forward, arms hanging straight down. The robot also returns here when the application starts.'],
 ['Head harness','The head half of the head light connector, with the eye input lead, the eye cable and the mouth lead.'],
 ['Head light cable','The strand’s three wires after light 5, with any extension, running up to the head light connector.'],
 ['Head light connector (HEAD LIGHT)','The second three-pin JST-SM pair (E10), between the body and the head. Its halves are the body half, on the head light cable, and the head half, on the head harness. The joined connector sits inside the head, on top of the mouth LED cassette (P30).'],
 ['Head shelf assembly','The head shelf (P08) with the head horn adapter (P14) and its horn screwed on. It is built on the bench and goes on the head servo.'],
 ['Insert (a wire into a WAGO)','Strip 11 mm, push the bare wire fully into the port and close the lever.'],
 ['J1','The power jack (E18), at the robot-left end of the base’s rear face. Its two contacts are the center and the sleeve.'],
 ['Light 0 to light 15','A place in the lighting data chain: body 0–5, eyes 6–7, mouth 8–15.'],
 ['Mouth lead','The other half of the cut JST-SH cable (E11). It runs from the second eye’s OUT socket to the mouth stick’s +5 V, GND and DIN pads.'],
 ['Pebble','One LED bead on the body light strand (E05).'],
 ['Pi power lead (PI POWER)','The micro-USB lead (E22) from W1 and W3 to the Pi.'],
 ['R1, R2','The button LED resistor (R1), 1 kΩ, and the data resistor (R2), 330 Ω.'],
 ['Robot-left, robot-right','The robot’s own sides. Robot-left is on your right when you face the robot.'],
 ['S1, S2','The two level shifters (E15).'],
 ['Seat','Push a plug or part fully home until it latches or sits flat.'],
 ['Servo cable labels (LEFT, RIGHT, HEAD)','The labels on the robot-left arm, robot-right arm and head servo cables.'],
 ['Strand input (INPUT)','The end of the body light strand that receives data. You mark it INPUT after it passes the light test.'],
 ['Test-fit','Fit parts without glue or final tightening to check the fit, then remove them.'],
 ['Test-route','Run a wire along its final path without fixing or soldering it, to find its length. Mark it, then return to the bench.'],
 ['W1, W2, W3, W4','The four WAGOs (E06): input WAGO (W1), servo power WAGO (W2), ground WAGO (W3) and servo ground WAGO (W4).'],
 ['W1/3 (a WAGO port)','WAGO W1, port 3. Ports are numbered 1 to 5 from the robot-right end of each WAGO.'],
 ['Wire, lead and cable','A wire is one insulated conductor. A lead comes attached to a component, or is a short purchased cable such as the Pi power lead. A cable is two or more wires that run together, usually to one plug.'],
 ['Wire bundle','Two or more wires tied together along one path. The step always says which wires.']
].map(([t,d])=>`<dt>${escape(t)}</dt><dd>${escape(d)}</dd>`).join('')}</dl>
 <h2>Reading the drawings</h2><p>The CAD views show the real part shapes in the robot’s orientation. The black base is drawn in a lighter color so its inside features show. Lines point to parts. Where labeled, arrows show the direction to insert or remove a part. In fastener views, circles mark screw seats and squares mark nuts.</p>
 <div class="actions"><a class="button primary" href="references.html">Datasheets</a><button id="all-steps">Show all steps for printing</button></div>`}

const softwareTopics=['overview','commands','settings','troubleshooting'];
function software(topic){
 const cmd=(line,label,context='computer')=>commandCard({kind:'command',context,label,lines:[line]});
 const lookup=(line,label,description)=>`<section class="software-command">${cmd(line,label)}<p>${description}</p></section>`;
 return `<article class="software-reference"><p class="eyebrow">Keep this page handy</p><h1 tabindex="-1">Software reference</h1><p class="lede">Commands, settings and help for the application running on your Pi.</p><div class="setup-cta"><div><strong>First time setting up the Pi?</strong><p>Follow the Pi software steps before mounting it in the base.</p></div><a class="button primary" href="#step-computer-ssh-key">Start Pi setup →</a></div>
 <nav class="software-topic-nav" aria-label="Software topics">${softwareTopics.map(id=>`<a href="#software/${id}"${topic===id?' aria-current="location"':''}>${{overview:'How it works',commands:'Commands',settings:'Settings',troubleshooting:'Troubleshooting'}[id]}</a>`).join('')}</nav>
 <section id="software-overview" class="software-section"><h2 tabindex="-1">How it works</h2><div class="software-overview"><div><p>One application runs on the Raspberry Pi, managed by <code>blooglyblob.service</code>. It handles the button, microphone, speakers, lights and servos, and uses OpenAI over the internet for conversation. Your computer is needed for setup and updates.</p><p>During a conversation, microphone audio streams to OpenAI. Conversations can also open for alert acknowledgements or resume after a dance.</p><p>The application starts on boot. Press the front button to start a conversation. While it cannot reach the internet, the body glows amber and the button does nothing. It returns to normal by itself when the connection comes back. The button does not turn the power off. Starting the application moves the servos to the fit position. It may also make a billable speech request to prepare its greeting.</p></div>${diagram('assets/community/software.svg','The single Pi application and its connections')}</div></section>
 <section id="software-commands" class="software-section"><h2 tabindex="-1">Commands</h2><p>Run computer commands from the repository folder. On Windows, use the same WSL environment and SSH key you used during setup.</p><h3>Status and logs</h3><div class="software-command-grid">${lookup('make pi-status','Application status','Shows whether the service is running. This does not test the microphone, wiring or physical build.')}${lookup('make pi-logs','Follow the log','Press Ctrl+C to stop following the log and return to your computer’s prompt. The service keeps running.')}</div>
 <h3>Start and stop</h3><p>Starting or restarting moves the head and arms to the fit position. Keep your hands clear of them.</p><div class="software-command-grid">${lookup('make pi-start','Start the application','Starts the installed service.')}${lookup('make pi-stop','Stop the application','Stops the service. The Pi stays powered.')}${lookup('make pi-restart','Restart the application','Use after changing the installed settings.')}</div>
 <h3>Update the application</h3><p>Get the latest repository code, then install it. An update restarts the service and preserves the Pi’s settings.</p><div class="software-command-grid">${cmd('git pull','Get the current code')}${cmd('make pi-update','Install the update')}</div><p>If it reports missing system prerequisites, follow the repair message and run <code>make pi-provision</code>. First installation is covered in ${S('software-install')}.</p>
 <h3>Connect or shut down</h3>${cmd('make pi-ssh','Open an SSH session')}<p>In that Pi session, use <code>exit</code> to return to your computer, or shut down before disconnecting power:</p>${cmd('sudo poweroff','Shut down the Pi','pi')}<p>Wait until the Pi’s green activity light stops flashing, then unplug the supply. With the base closed, you cannot see the light: wait at least 30 seconds after the SSH session disconnects.</p>
 <details class="software-tests"><summary>Hardware checks and servo fitting</summary><p>Use these after installation, with the matching hardware ready. Follow the relevant assembly step before running a physical test.</p><div class="software-command-grid">${lookup('make pi-check-audio','List audio devices','Lists devices without recording. It temporarily stops the application and restores it afterward if it was running.')}${lookup('make pi-test-audio','Play a test tone','Uses the configured speaker output; keep the volume comfortable.')}${lookup('make pi-test-mic','Record and play back','After the beep, speak for five seconds. It then plays the recording back.')}${lookup('make pi-test-neopixels','Test the lights',`Follow ${S('all-lights-test')}. Lights each of the 16 lights in turn and runs color patterns.`)}${lookup('make pi-servo-fit','Hold the fit position',`Follow ${S('fit-position')} and ${S('shelf-arms')}. Start with the head shelf and arms off their shafts. Seat them while it holds, then type STOP. This command leaves the application stopped.`)}</div><p>Audio and light checks restore the service afterward if it was running, which can move the servos. Run <code>make pi-stop</code> first when it must stay stopped. Servo fitting always leaves it stopped.</p></details></section>
 <section id="software-settings" class="software-section"><h2 tabindex="-1">Settings</h2>${table(['File','Purpose'],[['<code>.env</code> on your computer','Selects PI_HOST, PI_USER and the initial configuration file. These choose where deployment commands connect.'],['<code>config/app.env</code> on your computer','Private input for the first provisioning: OpenAI key, audio selection and optional integrations. Never commit or share it.'],['<code>/etc/blooglyblob/app.env</code> on the Pi','The installed application’s settings. On later provisioning and updates, these settings take precedence.']],'cards')}<p>To change an installed setting, open an SSH session, edit the Pi’s file, then leave SSH before restarting from your computer:</p>${cmd('make pi-ssh','Connect from your computer')}${cmd('sudoedit /etc/blooglyblob/app.env','Edit installed settings','pi')}${cmd('exit','Return to your computer','pi')}${cmd('make pi-restart','Apply the change')}
 <details><summary>Configuration names</summary>${table(['Setting','Purpose'],[['AUDIO_INPUT_DEVICE / AUDIO_OUTPUT_DEVICE','Unambiguous device-name fragments. A missing or ambiguous selected device prevents startup.'],['OPENAI_API_KEY','Your private API credential. API usage is billed separately from ChatGPT.'],['OPENAI_LIVE_MODEL / OPENAI_RESPONSES_MODEL / OPENAI_SPEECH_MODEL','Models for conversation, answers/actions and prepared speech. Your API account must have access to them.'],['OPENAI_VOICE / OPENAI_SPEECH_VOICE','Conversation voice and prepared-speech voice.'],['MIC_GAIN','Software microphone amplification, not speaker volume. Set 1 for no added amplification; tune after a voice test.'],['OPENAI_INACTIVITY_SECONDS / OPENAI_SESSION_MAX_SECONDS','Conversation inactivity and maximum duration limits.'],['TMDB_API_KEY / WATCHMODE_API_KEY / ROKU_IP / RING_TOKEN','Optional integrations; Ring is experimental. See the repository documentation.']].map(([key,value])=>[`<code>${key}</code>`,value]),'cards')}<p><a href="${REPO}/blob/main/config/app.env.example" target="_blank" rel="noreferrer">Current configuration example ↗</a></p></details></section>
 <section id="software-troubleshooting" class="software-section"><h2 tabindex="-1">Troubleshooting</h2>${table(['Message','What to do'],[['“Could not resolve hostname” or the connection times out','Check that the Pi is powered and on your Wi-Fi, and that <code>PI_HOST</code> in <code>.env</code> matches its hostname. If it still fails, set <code>PI_HOST</code> to the Pi’s IP address from your router’s device list.'],['“Use the documented Raspberry Pi 3 / 64-bit image” or “Use Raspberry Pi OS Lite Trixie with Python 3.13”',`Rewrite the card as in ${S('imager-choose')}.`],['Provisioning stops with a message starting “Wi-Fi”',`Provisioning moves only the one Wi-Fi network set in Imager. Do not delete network files to get past it. Write the card again with one network, as in ${S('imager-settings')}.`],['“AUDIO_INPUT_DEVICE must identify one available audio device” (or AUDIO_OUTPUT_DEVICE)','Check that the audio module and its extension are plugged in. Run <code>make pi-check-audio</code> to list the devices. In the installed settings, set both names to the name after “USB-Audio - ” in <code>cat /proc/asound/cards</code>.']],'cards')}<p><a href="${REPO}/blob/main/docs/software/setup.md" target="_blank" rel="noreferrer">Repository setup documentation ↗</a> · <a href="${REPO}/blob/main/docs/software/maintenance.md" target="_blank" rel="noreferrer">Maintenance and commissioning ↗</a></p></section></article>`;
}

function safetyHTML(){return `<article class="safety-reference"><p class="eyebrow">Before you build</p><h1 tabindex="-1">Safety & responsibility</h1><h2>Your build, your responsibility</h2><p>BlooglyBlob is a DIY electronics and robotics project. You are responsible for selecting components, printing, assembly, wiring, software configuration, inspection, testing, maintenance and use of your build, including any modifications. Evaluate whether you have the skills and equipment to do the work; get qualified help when needed. Following this guide or passing its checks does not establish that a build is safe, compliant or suitable for a particular person or purpose.</p><h2>Who it’s for and practical precautions</h2><p>BlooglyBlob is a hobby electronics project for adults, not a toy, and is not designed for children. Keep it, and especially its small magnets, away from young children.</p><ul><li>Soldering, cutting and printing involve hot surfaces, fumes and sharp tools. Follow equipment and material instructions; use suitable ventilation and protective equipment.</li><li>Use the specified Mean Well GST40A05-P1J supply and T1 A time-delay light fuse. Do not open the supply or work on mains wiring. Disconnect power before changing wiring; short circuits can cause burns or fire even at low voltage.</li><li>Keep fingers, hair and clothing away from servos and joints. Keep small parts away from young children and pets.</li><li>The hands attach with small, strong magnets. If swallowed, magnets can cause serious internal injury. Check that each magnet is fully set in cured epoxy and inspect the hands regularly. Keep loose magnets and detachable hands away from young children and pets. If a magnet may have been swallowed, get medical help immediately.</li><li>Keep the build dry, keep vents clear, and stop using it if wiring is damaged, parts overheat, or movement is obstructed. Do not leave powered tests unattended.</li><li>AI responses can be incorrect or inappropriate. Do not rely on the robot for emergency, medical or other safety-critical decisions.</li></ul><h2>Privacy, cloud AI and costs</h2><p>The robot’s microphone sends speech to OpenAI under your API account. Tell people who talk to the robot that its voice is AI-generated and that their conversations go to a cloud service. You are responsible for following OpenAI’s terms and usage policies, including its rules on use by children, and the laws where you live.</p><p>API usage is billed to your OpenAI account. Use its billing controls to limit what you can spend. You are responsible for all charges.</p><h2>No warranty or safety certification</h2><p>To the fullest extent allowed by applicable law, the project’s designs, print files, software, documentation and build instructions are supplied as is, without express or implied warranties, including merchantability, fitness for a particular purpose and noninfringement. The authors and contributors make no guarantee of accuracy, completeness, reliability, performance or safety, and do not represent that a build meets product-safety standards or regulatory requirements. Diagrams, test results, recommended components and completed checklists are not safety certification.</p><h2>Limits of liability</h2><p>To the fullest extent allowed by applicable law, the authors, contributors and copyright holders disclaim liability for injury, property damage, data loss or other loss arising from building, modifying or using this project. Build and use it at your own risk. Nothing in this notice excludes a liability, warranty or legal right that applicable law does not allow to be excluded. The project license and third-party terms continue to apply; this notice does not replace them or add restrictions to the open-source license.</p><p>BlooglyBlob is not affiliated with or endorsed by OpenAI, Adafruit, Raspberry Pi Ltd, Autodesk or any other manufacturer or service named in this project. Product names and trademarks belong to their owners.</p><p>See the <a href="${REPO}/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT license</a> and <a href="${REPO}/blob/main/LICENSING.md" target="_blank" rel="noreferrer">license scope</a>.</p></article>`}

function notFound(){return '<p class="eyebrow">Build guide</p><h1 tabindex="-1">Page not found</h1><p>This address doesn’t match a page in the guide.</p><div class="actions"><a class="button primary" href="#start">Meet BlooglyBlob</a><a class="button" href="#parts">Parts & supplies</a></div>'}
const pages={start,'before-you-start':beforeYouStart,parts:arg=>partsHTML(arg),cost:costHTML,hardware,software,electrical:electricalHTML,safety:safetyHTML,notes:notesHTML,all:()=>buildSteps.map(s=>stepHTML(s,true)).join('')};
let lastBase=null,partsScroll=0,firstRoute=true,disposeHero=()=>{};
function route(){
 const hash=decodeURIComponent(location.hash.slice(1)||'start');let [base,arg]=hash.split('/');
 if(base==='content')return;
 if(base==='printing'){base='step-print-plates';history.replaceState(null,'','#'+base+(arg?'/'+encodeURIComponent(arg):''));}
 // Plain step numbers such as #14 open that step.
 if(/^\d+$/.test(base)&&buildSteps[+base-1]){location.replace('#step-'+buildSteps[+base-1].id);return}
 if(lastBase==='parts')partsScroll=scrollY;
 const s=base.startsWith('step-')?stepMap[base.slice(5)]:null;
 const known=s||(pages[base]&&(!arg||base==='parts'||(base==='software'&&softwareTopics.includes(arg))));
 disposeHero();
 $('#page').innerHTML=s?stepHTML(s,false,arg):known?pages[base](arg):notFound();
 document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===base));
 if(base==='parts'){filterParts();$('#search').addEventListener('input',filterParts);$('#category').addEventListener('change',filterParts);$('#stock-filter').addEventListener('change',filterParts)}
 closeMenu();updateProgress();
 document.title=(s?`Step ${s.number} · ${s.title}`:known?(mainRefs.find(x=>x[0]===base)?.[1]||'All steps'):'Page not found')+' — BlooglyBlob build guide';
 window.scrollTo(0,base==='parts'&&!arg&&lastBase!=='parts'?partsScroll:0);
 if(base==='step-print-plates'&&partMap[arg]){const plate=prints.find(p=>p.parts.includes(arg));if(plate){$('#plate-settings').open=true;const card=document.getElementById(plate.id);card?.classList.add('selected-plate');card?.scrollIntoView({block:'start'});}}
 disposeHero=window.BGBHero?.mount(document.querySelector('[data-hero]'))||(()=>{});
 lastBase=base;
 document.querySelector('nav a.active')?.scrollIntoView({block:'nearest'});
 if(base==='software'&&softwareTopics.includes(arg)){const section=document.getElementById('software-'+arg);section?.scrollIntoView({block:'start'});section?.querySelector('h2')?.focus({preventScroll:true});}else if(!firstRoute)$('#page h1')?.focus({preventScroll:true});firstRoute=false;
}
function closeMenu(){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false')}
async function copyCode(button){
 const card=button.closest('.code-card'),code=card.querySelector('code'),status=card.querySelector('.copy-status');
 if(button.getAttribute('aria-busy')==='true')return;
 button.setAttribute('aria-busy','true');status.textContent='';
 try{
  if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');
  await navigator.clipboard.writeText(code.textContent);
  status.textContent='Copied.';
 }catch{
  card.querySelector('pre').focus();
  const range=document.createRange();range.selectNodeContents(code);
  const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);
  status.textContent='Copy is unavailable. Text selected: press Ctrl+C or Command+C, or use your device’s Copy menu.';
 }finally{button.removeAttribute('aria-busy');}
}
document.addEventListener('click',e=>{
 if(e.target.closest('[data-cost-materials]')){const heading=$('#cost-materials');heading.scrollIntoView({behavior:'smooth'});heading.focus({preventScroll:true});return;}
 const copy=e.target.closest('[data-copy-code]');
 if(copy){copyCode(copy);return;}
 const summary=e.target.closest('.reference-topic > summary');
 if(summary&&summary.parentElement.open){e.preventDefault();summary.parentElement.open=false;document.querySelector(`[aria-controls="${summary.parentElement.id}"]`)?.focus()}
 const topic=e.target.closest('[data-reference]');
 if(topic){const selected=document.getElementById(topic.getAttribute('aria-controls'));document.querySelectorAll('.reference-topic').forEach(el=>el.open=el===selected);selected.querySelector('summary').focus();selected.scrollIntoView({block:'start',behavior:'instant'})}
 const wiringDetail=e.target.closest('[data-wiring-detail]');
 if(wiringDetail){const view=document.querySelector('.master-window'),large=view.classList.toggle('is-detail');wiringDetail.setAttribute('aria-pressed',String(large));wiringDetail.textContent=large?'Fit diagram':'Larger labels';view.scrollTo({top:0,left:0,behavior:'instant'});view.focus({preventScroll:true})}
 const z=e.target.closest('[data-zoom]');
 if(z){$('#zoom').classList.remove('large');$('#zoom-image').classList.remove('detail-size');$('#detail-size').textContent='Larger view';$('#detail-size').setAttribute('aria-pressed','false');$('#zoom-image').src=z.dataset.zoom;$('#zoom-image').alt=z.querySelector('img')?.alt||z.closest('figure')?.querySelector('img')?.alt||'Enlarged diagram';$('#zoom').showModal()}
 if(e.target.id==='all-steps')location.hash='all';
 if(e.target.closest('.skip')){e.preventDefault();$('#content').focus()}
 if(document.body.classList.contains('menu-open')&&!e.target.closest('aside')&&!e.target.closest('#menu'))closeMenu();
});
document.addEventListener('toggle',e=>{if(!e.target.matches('.reference-topic'))return;const control=document.querySelector(`[aria-controls="${e.target.id}"]`);control?.setAttribute('aria-expanded',String(e.target.open));if(!e.target.open&&e.target.contains(document.activeElement))control?.focus()},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open')){closeMenu();$('#menu').focus()}});
document.addEventListener('change',e=>{if(e.target.name==='cost-filament'){const single=e.target.value==='single';$('#shopping-total').textContent=usd(single?costs.single_color_total:costs.shopping_total);$('#shopping-scope').textContent=shoppingScope(single);$('#shopping-list').innerHTML=shoppingHTML(single);return;}if(e.target.name==='slicer'){state.slicer=e.target.value;save();const article=e.target.closest('[data-print-slicer]');article.dataset.printSlicer=state.slicer;article.querySelector('.action-sequence').outerHTML=printInstructions(stepMap['print-plates']);return;}const s=e.target.dataset.step,p=e.target.dataset.stock;if(s){state.steps=e.target.checked?[...new Set([...state.steps,s])]:state.steps.filter(x=>x!==s);save()}if(p){state.stock=e.target.checked?[...new Set([...state.stock,p])]:state.stock.filter(x=>x!==p);save()}});
$('#detail-size').onclick=()=>{const large=$('#zoom-image').classList.toggle('detail-size');$('#zoom').classList.toggle('large',large);$('#detail-size').textContent=large?'Fit to screen':'Larger view';$('#detail-size').setAttribute('aria-pressed',String(large))};
$('#close-zoom').onclick=()=>$('#zoom').close();$('#zoom').addEventListener('click',e=>{if(e.target===$('#zoom'))$('#zoom').close()});
$('#menu').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(open));if(open)document.querySelector('nav a.active')?.scrollIntoView({block:'nearest'})};
// Print includes collapsed inventories and electrical lookup sections; restore the screen state afterward.
let printInventories=[];
window.addEventListener('beforeprint',()=>{printInventories=[...document.querySelectorAll('.bench-list:not([open]), .electrical-reference details:not([open])')];printInventories.forEach(el=>el.open=true)});
window.addEventListener('afterprint',()=>{printInventories.forEach(el=>el.open=false);printInventories=[]});
window.addEventListener('hashchange',route);route();
